// Version 4 (relationships): a material that lures, a landmark that lures and scares. Expect: the landmark stands with its lures, the honey is on the ground.
const spell = {
  materials: [{ name: "honeycomb", layer: "cover", color: "#e8b030", lures: ["bear", "boar"], flammable: 0.6 }],
  *cast(w) {
    w.sound("chime", 0.25);
    w.landmark(w.x, w.y, { name: "Honey Shrine", lures: ["bear"], scares: ["wolf"], radius: 8, color: "#e8b030" });
    w.ring(w.x, w.y, 2, 4, (x, y) => w.set(x, y, "honeycomb"));
    yield 0.5;
  },
};

// Version 5 (bodies): a creature with a body plan, features, a second color and a model. Expect: two herons alive, drawn as birds with wings.
const spell = {
  creatures: [
    { name: "glass heron", base: "bird", body: "bird", color: "#bfe8ff", color2: "#5a8ab0", features: ["wings", "tail"],
      flying: true, speed: 4, hp: 30, radius: 0.5, behavior: "wander", lures: ["fish"] },
  ],
  *cast(w) {
    w.sound("whoosh", 0.3);
    w.burst(w.x, w.y, { count: 12, colors: ["#bfe8ff", "#ffffff"], speed: 2, up: 3 });
    yield 0.3;
    w.spawn("glass heron", w.x - 2, w.y);
    w.spawn("glass heron", w.x + 2, w.y);
  },
};

// Version 6, artifacts: places two lamps, finds them again with w.artifacts and fills their charges, and draws a ring for a moment. Expect: two lamps with 5 charges each, a drawing that draws.
const spell = {
  artifacts: [{ name: "Road Lamp", radius: 6, color: "#ffd36a", charges: 1, recharge: 60, effects: [{ when: "night", do: "light" }] }],
  *cast(w) {
    w.sound("chime", 0.25);
    w.artifact(w.x - 3, w.y, "Road Lamp");
    w.artifact(w.x + 3, w.y, "Road Lamp");
    yield 0.2;
    for (const lamp of w.artifacts(w.x, w.y, 6)) lamp.charges = 5;
    w.draw((ctx, t) => {
      ctx.strokeStyle = "#ffd36a";
      ctx.beginPath();
      ctx.arc(w.x, w.y, 3 + t, 0, Math.PI * 2);
      ctx.stroke();
    }, 1.5);
  },
};
